'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=v=>/^https?:\/\//i.test(v||'')?esc(v):'#';
const fmt=(v,d=0)=>Number(v).toLocaleString('en-US',{maximumFractionDigits:d,minimumFractionDigits:d});
const pct=(v,d=1)=>`${v>0?'+':''}${fmt(v,d)}%`;
const date=v=>{if(!v)return 'Date not supplied';if(/^\d{4}$/.test(v))return v;if(/^\d{4}-\d{2}$/.test(v))return new Date(v+'-15T00:00:00+07:00').toLocaleDateString('en-GB',{month:'short',year:'numeric',timeZone:'Asia/Jakarta'});const dt=new Date(v.length===10?v+'T00:00:00+07:00':v);return Number.isNaN(dt.getTime())?String(v):dt.toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'Asia/Jakarta'})};
const quoteDate=v=>v?new Date(v).toLocaleString('en-GB',{day:'numeric',month:'short',hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jakarta'})+' WIB':'Time not supplied';
const I={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',markets:'<path d="M3 3v18h18M6 15l5-6 4 3 6-8"/>',intelligence:'<path d="M4 4h16v16H4zM8 8h8M8 12h8M8 16h4"/>',ecosystem:'<circle cx="12" cy="12" r="3"/><circle cx="4" cy="4" r="2"/><circle cx="20" cy="4" r="2"/><circle cx="4" cy="20" r="2"/><circle cx="20" cy="20" r="2"/><path d="m6 6 4 4m4-4-4 4m-4 4-4 4m8-4 4 4"/>',portfolio:'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V3h8v4M3 12h18M10 12v3h4v-3"/>',deals:'<path d="M4 4h5v16H4zM10 4h5v10h-5zM16 4h5v14h-5z"/>',competitors:'<path d="M4 20V8h4v12M10 20V3h4v17M16 20V11h4v9"/>',research:'<path d="M5 3h10l4 4v14H5zM14 3v5h5M8 12h8M8 16h5"/>',ir:'<path d="m3 8 9-5 9 5H3M5 10v8m7-8v8m7-8v8M3 21h18"/>',valuation:'<rect x="5" y="2" width="14" height="20" rx="2"/><path d="M8 5h8v4H8zM8 13h2m4 0h2m-8 4h2m4 0h2"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',external:'<path d="M14 3h7v7m0-7L10 14M10 3H3v18h18v-7"/>',download:'<path d="M12 3v12m-5-5 5 5 5-5M4 15v6h16v-6"/>',refresh:'<path d="M20 7v5h-5M4 17v-5h5M6 7a7 7 0 0 1 12-2l2 3M4 16l2 3a7 7 0 0 0 12-2"/>',alert:'<path d="m12 3 10 18H2L12 3zm0 6v5m0 3h.01"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',check:'<path d="m4 12 5 5L20 6"/>'};
const icon=(key)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${I[key]||I.intelligence}</svg>`;
const NAV=[['overview','Decision brief','overview'],['markets','Markets & peers','markets'],['economics','Economic indicators','markets'],['financials','Financials','competitors'],['valuation','Valuation','valuation'],['actions','Corporate actions','portfolio'],['ecosystem','Ecosystem map','ecosystem'],['portfolio','Portfolio & risk','portfolio'],['competitors','Competitors','competitors'],['deals','Deal sourcing','deals'],['intelligence','Intelligence feed','intelligence'],['research','Research library','research'],['investor-relations','IR hub','ir'],['system','How the agent works','refresh']];
let D, WORLD, view='overview', S={market:'GOTO',timeframe:'3M',chartMode:'provider',newsFilter:'All',newsQuery:'',mapView:'landscape',mapType:'All',mapQuery:'',mapCountry:'All',mapRegion:'sea',docFilter:'All',docQuery:'',dealView:'pipeline',dealFilter:'All'};
function readLocal(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let saved=readLocal('goto-intel-saved',[]), stages=readLocal('goto-intel-stages',{}), notes=readLocal('goto-intel-notes',{});
function persist(){try{localStorage.setItem('goto-intel-saved',JSON.stringify(saved));localStorage.setItem('goto-intel-stages',JSON.stringify(stages));localStorage.setItem('goto-intel-notes',JSON.stringify(notes))}catch{toast('Browser storage unavailable. Export your notes before closing.')}}
const tag=(v,cls='')=>`<span class="tag ${cls}">${esc(v)}</span>`;
const companyLogo=(name,id='',full=false)=>{const record=D?.entities.find(e=>e.id===id||e.name.toLowerCase()===name.toLowerCase());const asset=D?.logos?.[id]?.path?D.logos[id]:record?.logo||record?.logoUrl;const src=typeof asset==='string'?asset:asset?.path||asset?.localPath;return `<span class="company-logo ${id.toLowerCase()} ${full?'full-logo':''}">${src?`<img src="${esc(src)}" alt="${esc(name)} logo" loading="lazy"><span class="logo-fallback" hidden>${esc(name)}</span>`:esc(({'GoTo Group':'go','GoTo':'go','Grab Holdings':'Gr','Grab':'Gr','Sea Limited':'Sea','Sea':'Sea','Bank Jago':'J','Moka':'M','Argor Capital':'A','Bintang Kecil':'BK','Xurya':'X'}[name])||name.split(' ').map(x=>x[0]).join('').slice(0,2))}</span>`};
const title=(eye,name,description,actions='')=>`<div class="page-head"><div><div class="eyebrow">${eye}</div><h1>${name}</h1><p class="page-description">${description}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
const metric=(label,value,foot,cls='',ico='markets')=>`<div class="card metric"><div class="metric-label">${label}${icon(ico)}</div><div class="metric-value mono ${cls}">${value}</div><div class="metric-foot">${foot}</div></div>`;
const sourceLink=(url,label='Open original source')=>url?`<a class="drawer-source" href="${safeUrl(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} ↗</a>`:'';
function gotoMetric(k){return D.metrics.find(m=>m.key===k)||{value:null,label:k}}
function competitorMetric(company,label,scope='Group'){return D.competitorMetrics.find(m=>m.company_id===company&&m.label===label&&m.scope===scope)}
function sourceFor(id){return D.sources.find(s=>s.id===id)}
function allSources(){const out=new Map();D.sources.forEach(s=>out.set(s.url,s));[...D.documents.map(d=>({url:d.url,title:d.title,publisher:d.publisher,date:d.date,evidence:d.evidence})),...D.events.map(e=>({url:e.sourceUrl,title:e.title,publisher:e.publisher,date:e.date,evidence:e.evidence})),...D.reports.map(r=>({url:r.sourceUrl,title:r.title,publisher:r.publisher,date:r.report_date,evidence:'Full report reviewed'}))].forEach(s=>{if(s.url&&!out.has(s.url))out.set(s.url,s)});return [...out.values()]}
function asset(ticker){return D.markets.assets.find(a=>a.ticker===ticker)}
function price(a){return a.currency==='IDR'?'Rp'+fmt(a.price):'$'+fmt(a.price,2)}
function quotes(){return `<div class="quote-strip">${D.markets.assets.map(a=>`<button class="quote-item" data-market="${a.ticker}">${companyLogo(a.name,({'GOTO':'goto','SE':'sea','ARTO':'jago','UBER':'uber'}[a.ticker]||a.ticker.toLowerCase()))}<div><b>${a.ticker}</b><span class="quote-price mono">${price(a)}</span></div><span class="quote-change ${a.changePct>=0?'positive':'negative'}">${pct(a.changePct)}</span><small class="quote-asof">${a.snapshotRetrievedAt?'Snapshot ':''}${date(a.snapshotRetrievedAt||a.quoteAsOf).replace(' 2026','')}</small></button>`).join('')}</div>`}
function eventRow(e){return `<article class="event" tabindex="0" role="button" data-event="${e.id}"><div class="event-icon">${icon(e.category==='Portfolio news'?'ecosystem':e.category==='Corporate action'?'portfolio':e.category==='Competitor'?'competitors':'intelligence')}</div><div><div class="event-meta">${tag(e.category,e.category==='Portfolio news'?'green':'')}<span>${date(e.date)}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p></div><span class="event-arrow">↗</span></article>`}
function eventCard(e){return `<article class="card news-card" data-event="${e.id}" tabindex="0" role="button">${e.image?.url?`<div class="news-image"><img src="${safeUrl(e.image.url)}" alt="${esc(e.title)} — official company announcement" loading="lazy"><small>${esc(e.image.credit)} · source image</small></div>`:''}<div class="news-card-meta">${tag(e.category,e.category==='Portfolio news'?'green':e.category==='Economics'?'amber':'blue')}<button class="saved-btn ${saved.includes(e.id)?'saved':''}" data-save="${e.id}" aria-label="${saved.includes(e.id)?'Unsave':'Save'} ${esc(e.title)}">${saved.includes(e.id)?'★':'☆'}</button></div><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p><div class="business-tags">${tag(e.company)}${e.topic&&e.topic!==e.category?tag(e.topic,'outline'):''}</div><div class="news-card-footer"><span>${date(e.date)}</span><span>${esc(e.publisher)} ↗</span></div></article>`}
function miniMap(){return `<div class="mini-map"><svg viewBox="0 0 460 250"><path d="M230 125C180 125 170 50 110 50M230 125C180 125 170 200 110 200M230 125C280 125 290 50 350 50M230 125C280 125 290 200 350 200M230 125H80M230 125H390"/>${[['goto','GoTo',230,125,'core'],['gojek','Gojek',110,50,''],['gopay','GoPay',350,50,''],['moka','Moka',75,125,''],['argor','Argor',385,125,''],['jago','Bank Jago',110,200,''],['xurya','Xurya',350,200,'']].map(([id,label,x,y,cls])=>`<g class="map-mini-node ${cls}" tabindex="0" role="button" data-entity="${id}" transform="translate(${x-40},${y-18})"><rect width="80" height="36" rx="7"/><text x="40" y="22" text-anchor="middle">${label}</text></g>`).join('')}</svg></div><div class="map-caption"><span><i class="dot"></i>Operating ecosystem</span><span><i class="dot blue"></i>Holdings & funds</span><span><i class="dot amber"></i>Historical links</span></div>`}
function barChart(){const qs=D.quarterly, max=Math.max(...qs.flatMap(q=>[q.odsEbitda,q.fintechEbitda]));return `<div class="bar-chart">${qs.map(q=>`<div class="bar-group"><div class="bar" style="height:${q.odsEbitda/max*100}%;background:#d2e2ca"><span>${fmt(q.odsEbitda)}</span></div><div class="bar" style="height:${q.fintechEbitda/max*100}%;background:#7ba477"><span>${fmt(q.fintechEbitda)}</span></div><small>${q.period}</small></div>`).join('')}</div><div class="chart-legend"><span><i class="dot" style="background:#d2e2ca"></i>On-demand Services</span><span><i class="dot" style="background:#7ba477"></i>Fintech</span></div><p class="chart-note">Adjusted EBITDA · IDR billion. Q1 flows calculated as reported H1 less Q2. Company-defined measures; segment totals exclude e-commerce and unallocated group items.</p>`}
function overview(){const revenue=gotoMetric('netRevenue'), eb=gotoMetric('adjustedEbitda'), news=D.events.filter(e=>e.category==='Portfolio news').slice(0,3);return title('THE CORPORATE DEVELOPMENT WORKSPACE','GoTo corporate development cockpit','A decision brief across markets, corporate actions, competitors, investments and potential deals.',`<button class="button" data-action="export-brief">${icon('download')}Export brief</button><button class="button primary" data-nav="intelligence">Explore intelligence ${icon('arrow')}</button>`)+`<div class="metric-grid">${metric('GoTo net revenue',`Rp${fmt(revenue.value/1000,1)}tn`,`${tag('+31% YoY','green')} Q2 2026 · reported`)}${metric('Group adjusted EBITDA',`Rp${fmt(eb.value)}bn`,`${tag('Q2 2026','green')} Company-defined measure`)}${metric('Mapped ecosystem',fmt(D.entities.length),`Companies, products & investment links`,'','ecosystem')}${metric('Investor relations library',fmt(D.documents.length),`Official documents & disclosure directories`,'','research')}</div><section class="card hero-card"><div class="hero-orbit"></div><div><div class="eyebrow">ON THE DECISION RADAR · 14 OCTOBER</div><h2>Follow the capital. Understand the connections.</h2><p>GoTo's proposed treasury-share cancellation is approaching its shareholder vote. Track the resolution, effective date and share-count basis before changing valuation assumptions.</p></div><button class="button" data-event="${D.events.find(e=>/agenda|treasury.*proposal/i.test(e.title))?.id||'g1'}">Review corporate action ↗</button></section>${quotes()}<div class="grid-2"><section class="card"><div class="card-head"><div><h2>What changed across the ecosystem</h2><p>Recent company news, operating developments and economic releases</p></div><button class="text-link" data-nav="intelligence">View all updates ↗</button></div>${D.events.slice(0,4).map(eventRow).join('')}</section><section class="card"><div class="card-head"><div><h2>The ecosystem, connected</h2><p>Explore operating businesses, investments and fund relationships</p></div><button class="text-link" data-nav="ecosystem">Open map ↗</button></div>${miniMap()}<div class="trust-line"><span><b>${D.entities.length}</b> entities</span><span><b>${D.relationships.length}</b> relationships</span><span>Evidence linked</span></div></section></div><div class="grid-equal section-gap"><section class="card"><div class="card-head"><div><h2>Profitability is shifting</h2><p>GoTo's operating segments · quarterly comparison</p></div>${tag('Official results','green')}</div>${barChart()}</section><section class="card"><div class="card-head"><div><h2>Beyond the financial statements</h2><p>Public business developments from the venture network</p></div><button class="text-link" data-nav="portfolio">Portfolio monitor ↗</button></div>${news.map(eventRow).join('')}</section></div><div class="grid-3 section-gap">${D.macro.filter(x=>!x.stale).slice(0,3).map(x=>`<article class="card"><div class="metric-label">${esc(x.label)}${icon('markets')}</div><div class="metric-value">${Array.isArray(x.value)?x.value.join('–'):fmt(x.value,2)}%</div><div class="metric-foot">${esc(x.period)}</div><p class="tiny muted" style="margin-top:12px">${esc(x.implication)}</p></article>`).join('')}</div>`}
function svgChart(series,timeframe,compare=false){const width=900,height=300,pad={left:48,right:30,top:23,bottom:40};const all=series.flatMap(s=>s.points.map(p=>compare?p.value/s.points[0].value*100:p.value));if(!all.length)return '<div class="empty">No audited historical series available. Use the provider chart.</div>';let low=Math.min(...all),high=Math.max(...all);let spread=high-low||Math.max(high*.01,1);low-=spread*.1;high+=spread*.13;const start=Math.min(...series.map(s=>new Date(s.points[0].timestamp).getTime())),end=Math.max(...series.map(s=>new Date(s.points.at(-1).timestamp).getTime()));const x=t=>pad.left+(new Date(t).getTime()-start)/Math.max(end-start,1)*(width-pad.left-pad.right),y=v=>pad.top+(high-v)/(high-low)*(height-pad.top-pad.bottom);let content='';for(let i=0;i<5;i++){const v=low+(high-low)*i/4,yy=y(v);content+=`<line x1="${pad.left}" x2="${width-pad.right}" y1="${yy}" y2="${yy}" stroke="#e8eee3" stroke-dasharray="3 4"/><text class="axis-label" x="${pad.left-9}" y="${yy+3}" text-anchor="end">${fmt(v,compare?0:v<10?2:0)}</text>`}for(let i=0;i<5;i++){let t=start+(end-start)*i/4;content+=`<text class="axis-label" x="${x(t)}" y="${height-10}" text-anchor="middle">${new Date(t).toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'Asia/Jakarta'})}</text>`}series.forEach(s=>{const path=s.points.map((p,i)=>`${i?'L':'M'}${x(p.timestamp).toFixed(2)},${y(compare?p.value/s.points[0].value*100:p.value).toFixed(2)}`).join(' ');if(!compare)content+=`<path d="${path} L${x(s.points.at(-1).timestamp)},${height-pad.bottom} L${x(s.points[0].timestamp)},${height-pad.bottom}Z" fill="${s.color}" fill-opacity=".07"/>`;content+=`<path d="${path}" fill="none" stroke="${s.color}" stroke-width="2.2"/>`;s.points.forEach(p=>content+=`<circle cx="${x(p.timestamp)}" cy="${y(compare?p.value/s.points[0].value*100:p.value)}" r="7" fill="transparent"><title>${esc(s.ticker)} · ${p.date||p.timestamp.slice(0,10)} · ${fmt(p.value,2)}${compare?' · index '+fmt(p.value/s.points[0].value*100,1):''}</title></circle>`)});return `<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${compare?'Indexed stock comparison':'Historical daily closing prices'} for ${series.map(s=>s.ticker).join(', ')}">${content}</svg>`}
function markets(){const a=asset(S.market),colors=['#3a8559','#c7894f','#758abd','#877cab'];const compareSeries=D.markets.assets.filter(a=>a.ticker!=='GOTO'&&a.pointsByTimeframe[S.timeframe]?.length).map((a,i)=>({ticker:a.ticker,points:a.pointsByTimeframe[S.timeframe],color:colors[i]}));const points=a.pointsByTimeframe[S.timeframe];let chart;if(S.chartMode==='compare')chart=`<div class="chart-container">${svgChart(compareSeries,S.timeframe,true)}</div><div class="chart-legend">${compareSeries.map(s=>`<span><i class="dot" style="background:${s.color}"></i>${s.ticker}</span>`).join('')}</div><p class="chart-note">Indexed to 100 at each series' first observed close. Local-currency price returns exclude dividends and FX. GOTO is omitted because the downloaded history failed quality checks. Different exchanges have different trading calendars.</p>`;else if(S.chartMode==='history'&&points.length)chart=`<div class="chart-container">${svgChart([{ticker:a.ticker,points,color:'#548a5f'}],S.timeframe)}</div><p class="chart-note">${a.provider} · unadjusted daily closes · ${a.currency} · ends ${date(a.actualAsOf)}. Hover a chart point for its exact price and date. Missing bars are omitted, not synthesized.</p>`;else chart=`<div class="tradingview-shell" id="liveChart"><div class="empty">Loading ${esc(a.ticker)} interactive chart…<br><a href="${safeUrl(a.providerChartUrl)}" target="_blank" rel="noopener" class="source-link">Open TradingView ↗</a></div></div><p class="chart-note">Interactive TradingView chart · provider-controlled updates and market-data delay. Quote cards above are timestamped snapshots.</p>${a.ticker==='GOTO'?'<div class="quality-note">GOTO downloaded history failed a repeated-close check. The interactive provider chart is shown instead of plotting doubtful historical data.</div>':''}`;return title('PUBLIC MARKETS','Market monitor','Follow GOTO, Grab, Sea and relevant peers. Keep quote snapshots, historical prices and provider charts distinct.',`<button class="button" data-action="refresh-quotes">${icon('refresh')}Refresh IDX quotes</button><a class="button primary" href="${safeUrl(a.providerChartUrl)}" target="_blank" rel="noopener">TradingView ${icon('external')}</a>`)+quotes()+`<div class="market-layout"><section class="card chart-card"><div class="card-head"><div><h2>${esc(a.name)} <span class="muted tiny">${a.exchange}:${a.ticker}</span></h2><p>${price(a)} · ${quoteDate(a.snapshotRetrievedAt||a.quoteAsOf)}${a.snapshotRetrievedAt?' · retrieved snapshot':''} · ${esc(a.provider)}</p></div><div class="segmented">${['1M','3M','6M'].map(x=>`<button class="${S.timeframe===x?'active':''}" data-timeframe="${x}">${x}</button>`).join('')}</div></div><div class="chart-controls">${D.markets.assets.map(x=>`<button class="asset-tab ${x.ticker===S.market?'active':''}" data-chart-asset="${x.ticker}">${x.ticker}</button>`).join('')}<div class="segmented" style="margin-left:auto">${[['provider','Interactive'],['history','Daily closes'],['compare','Compare']].map(([id,label])=>`<button class="${S.chartMode===id?'active':''}" data-chartmode="${id}">${label}</button>`).join('')}</div></div>${chart}</section><section class="card"><div class="card-head"><div><h2>Coverage & quotes</h2><p>Local currencies · provider timestamps</p></div></div>${D.markets.assets.map(x=>`<div class="quote-list-row" data-market="${x.ticker}" tabindex="0" role="button">${companyLogo(x.name,x.ticker.toLowerCase())}<div><b>${x.ticker}</b><small>${x.exchange} · ${x.currency}</small></div><div class="quote-detail"><b>${price(x)}</b><small class="${x.changePct>=0?'positive':'negative'}">${pct(x.changePct)}</small></div></div>`).join('')}<div class="insight-box"><b>Connected to valuation</b>Market prices belong to the listed parent. A fund's assets under management and a startup funding round are different measures.</div>${D.markets.runtimeQuoteEndpoint.lastRefreshed?`<p class="chart-note">IDX gateway retrieved ${quoteDate(D.markets.runtimeQuoteEndpoint.lastRefreshed)}. This is retrieval time, not an exchange trade timestamp.</p>`:''}</section></div><div class="card section-gap"><div class="card-head"><div><h2>Economic context</h2><p>Official releases and explicitly dated archived market indicators</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Indicator</th><th>Value</th><th>Measurement period</th><th>Evidence status</th><th>GoTo transmission</th></tr></thead><tbody>${D.macro.map(x=>`<tr><td>${esc(x.label)}</td><td>${Array.isArray(x.value)?x.value.join('–'):fmt(x.value,x.value<100?2:0)} ${esc(x.unit)}</td><td>${esc(x.period)}</td><td>${tag(x.stale?'Archived snapshot':x.kind==='central_bank_forecast'?'Forecast':'Official release',x.stale?'amber':'green')}</td><td style="white-space:normal;min-width:220px">${esc(x.implication)}</td></tr>`).join('')}</tbody></table></div></div>`}
function economicValue(m){const values=Array.isArray(m.value)?m.value.map(v=>fmt(v,1)).join('–'):fmt(m.value,Number.isInteger(m.value)?0:Math.abs(m.value)<100?2:Math.abs(m.value)<1000?1:0);return values+(/percent|%/i.test(m.unit)?'%':'')}
function economics(){const indicators=D.economicIndicators||D.macro;const groups=['All',...new Set(indicators.map(x=>x.pillar||'Markets & policy'))];const list=indicators.filter(x=>!S.economicPillar||S.economicPillar==='All'||(x.pillar||'Markets & policy')===S.economicPillar);const featured=['bi-rate','cpi','usd-idr','ihsg'].map(id=>indicators.find(x=>x.id===id)).filter(Boolean);const histories=indicators.filter(x=>Array.isArray(x.history)&&x.history.filter(p=>p.timestamp&&!p.isPartial).length>1);return title('THE ECONOMIC TRANSMISSION DESK','Economic indicators','Monitor Indonesia demand, monetary policy, prices, credit conditions, external balances and public markets—with period-specific evidence.')+`<div class="metric-grid">${featured.map(x=>metric(esc(x.label),economicValue(x),esc(x.period),x.stale?'muted':'' )).join('')}</div><div class="filters"><select class="filter-select" id="economicPillar">${groups.map(g=>`<option ${g===(S.economicPillar||'All')?'selected':''}>${esc(g)}</option>`).join('')}</select><span class="filter-count">${list.length} economic & market indicators</span></div><section class="card"><div class="card-head"><div><h2>Economic conditions, translated</h2><p>Actual releases, forecasts and quote snapshots remain separate.</p></div>${tag('Primary sources + audited prices','green')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Indicator</th><th>Value</th><th>Measurement period</th><th>Evidence</th><th>Implication for GoTo</th><th>Source</th></tr></thead><tbody>${list.map(x=>`<tr><td><b>${esc(x.label)}</b><small style="display:block;color:#91a482;margin-top:5px">${esc(x.pillar||'Markets & policy')}</small></td><td>${economicValue(x)}<small style="display:block;color:#91a482;margin-top:5px">${esc(x.unit)}</small></td><td style="white-space:normal;min-width:140px">${esc(x.period?.includes('T')?quoteDate(x.period):x.period)}</td><td>${tag(x.stale?'Archived':/forecast/i.test(x.kind||x.status)?'Forecast':/snapshot|quote/i.test(x.kind||x.status)?'Market snapshot':'Reported',x.stale||/forecast/i.test(x.kind||x.status)?'amber':'green')}<small style="display:block;color:#91a482;margin-top:6px">${date(x.publicationDate||x.publishedAt||x.source_date||x.quoteAsOf)}</small></td><td style="white-space:normal;min-width:230px">${esc(x.implication)}</td><td><a class="text-link" href="${safeUrl(x.sourceUrl||sourceFor(x.source_id)?.url)}" target="_blank" rel="noopener">Open ↗</a></td></tr>`).join('')}</tbody></table></div></section>${histories.length?`<div class="grid-3 section-gap">${histories.slice(0,3).map(x=>`<article class="card"><div class="card-head"><div><h2>${esc(x.label)}</h2><p>${esc(x.unit)} · provider daily closes</p></div></div><div class="chart-container" style="height:200px">${svgChart([{ticker:x.label,points:x.history.filter(p=>p.timestamp&&!p.isPartial).map(p=>({timestamp:p.timestamp,value:p.value??p.close})),color:'#5c8955'}],'1M')}</div><p class="chart-note">Actual observations only. Latest quote timestamp can differ from last completed daily close.</p></article>`).join('')}</div>`:''}<div class="grid-3 section-gap">${[['Demand & affordability','Consumer confidence, retail activity, employment and inflation inform mobility frequency and merchant demand.'],['Funding & risk','Policy rates, bank credit and currency conditions affect lending economics, financing structures and discount rates.'],['Digital adoption','Payment growth informs distribution potential. Ecosystem-wide growth does not establish GoPay market-share gains.']].map(([name,desc])=>`<article class="card"><div class="eyebrow">CORPORATE-DEVELOPMENT TRANSMISSION</div><h3>${name}</h3><p class="tiny muted" style="margin-top:12px">${desc}</p></article>`).join('')}</div>`}
function intelligence(){const categories=['All','GoTo update','Corporate action','Competitor','Portfolio news','Economics'];const filtered=D.events.filter(e=>(S.newsFilter==='All'||e.category===S.newsFilter)&&JSON.stringify(e).toLowerCase().includes(S.newsQuery.toLowerCase()));return title('SIGNALS → IMPLICATIONS','Intelligence feed','Business news, company mentions, product launches, funding, regulation and results—with a source trail and a next action.',`<button class="button" data-action="export-events">${icon('download')}Export updates</button>`)+`<div class="filters"><input class="filter-input" id="newsSearch" type="search" placeholder="Search a company, topic or development" value="${esc(S.newsQuery)}"><select class="filter-select" id="newsCategory">${categories.map(x=>`<option ${x===S.newsFilter?'selected':''}>${x}</option>`).join('')}</select><span class="filter-count">${filtered.length} source-linked updates</span></div><div class="news-grid">${filtered.map(eventCard).join('')||'<div class="empty">No updates match these filters.</div>'}</div>`}
function mapNodes(){return D.entities.filter(e=>(S.mapType==='All'||e.category===S.mapType)&&`${e.name} ${e.sector} ${e.type} ${e.status}`.toLowerCase().includes(S.mapQuery.toLowerCase()))}
function entityNode(e){return `<button class="entity-node ${/unresolved|historical|unknown|unverified/i.test(e.status)?'unresolved':''}" data-entity="${e.id}"><span class="node-indicator"></span>${companyLogo(e.name,e.id)}<span><b>${esc(e.name)}</b><small>${esc(e.sector||e.type)}</small></span></button>`}
function landscape(nodes){const tiles=items=>items.map(e=>`<button class="logo-tile ${/unresolved|historical|unknown|unverified/i.test(e.status)?'historical':''}" data-entity="${e.id}" title="${esc(e.type+' · '+e.status)}">${companyLogo(e.name,e.id,true)}<b>${esc(e.name)}</b><small>${e.stakePct!=null?e.stakePct+'% effective':esc(e.type)}</small></button>`).join('');const block=(label,items,wide=false)=>items.length?`<section class="landscape-sector ${wide?'wide':''}"><div class="sector-ribbon">${label}<span>${items.length}</span></div><div class="logo-grid">${tiles(items)}</div></section>`:'';const inside=nodes.filter(e=>['On-demand','Financial services'].includes(e.category));const capital=nodes.filter(e=>['Strategic holdings','Venture network'].includes(e.category));const left=block('Mobility & delivery',inside.filter(e=>e.category==='On-demand'),true)+block('Payments & financial infrastructure',inside.filter(e=>['gopay','midtrans','dkab','mab','mapan-reksa','gopaylater'].includes(e.id)),true)+block('Merchant operating tools',inside.filter(e=>['moka','gobiz','selly'].includes(e.id)),true)+block('Competitive ecosystems',nodes.filter(e=>e.category==='Competitors'),true);const right=block('Holding vehicles',capital.filter(e=>['sbr','bintang-kecil'].includes(e.id)))+block('Strategic associates',capital.filter(e=>['tokopedia','jago'].includes(e.id)))+block('Funds & historical investment links',capital.filter(e=>['argor','goto-ventures','xurya'].includes(e.id)),true)+block('Argor-reported venture portfolio',capital.filter(e=>e.type==='Argor-reported portfolio company'),true)+block('Potential strategic counterparties',nodes.filter(e=>e.category==='Sourcing universe'),true);return `<div class="landscape-board"><section class="landscape-panel"><header><span class="panel-number">01</span><div><h2>Operating ecosystem</h2><p>Services, capabilities and competitive context</p></div></header><div class="landscape-sectors">${left||'<p class="empty">No operating companies match the current filters.</p>'}</div></section><section class="landscape-panel"><header><span class="panel-number">02</span><div><h2>Capital & strategic network</h2><p>Ownership, fund backing and sourcing universe</p></div></header><div class="landscape-sectors">${right||'<p class="empty">No investments match the current filters.</p>'}</div></section></div>`}
function network(nodes){let visible=nodes.filter(e=>!['Competitors','Sourcing universe'].includes(e.category));if(!visible.some(e=>e.id==='goto'))visible.unshift(D.entities.find(e=>e.id==='goto'));const ids=new Set(visible.map(e=>e.id)),relations=D.relationships.filter(r=>ids.has(r.from)&&ids.has(r.to));const levels=new Map([['goto',0]]);for(let pass=0;pass<8;pass++)relations.forEach(r=>{if(levels.has(r.from)&&!levels.has(r.to))levels.set(r.to,levels.get(r.from)+1)});visible.forEach(e=>{if(!levels.has(e.id))levels.set(e.id,e.id==='goto-ventures'?1:e.id==='xurya'?2:1)});const groups=[...new Set(levels.values())].sort((a,b)=>a-b),positions=new Map(),counts=groups.map(l=>visible.filter(e=>levels.get(e.id)===l).length),height=Math.max(520,Math.max(...counts)*78+70),width=Math.max(1000,(groups.length+1)*230);groups.forEach(l=>{const rows=visible.filter(e=>levels.get(e.id)===l);rows.forEach((e,i)=>positions.set(e.id,{x:40+l*240,y:rows.length===1?height/2:45+i*(height-90)/Math.max(rows.length-1,1)}))});const edges=relations.map(r=>{const from=positions.get(r.from),to=positions.get(r.to),historical=/historical|fund backing|reported fund/i.test(r.type);return `<path class="edge ${historical?'unverified':''}" d="M${from.x+155},${from.y}C${from.x+210},${from.y} ${to.x-50},${to.y} ${to.x},${to.y}"><title>${esc(r.type)}${r.stakePct!==null?' · '+r.stakePct+'%':''} · ${esc(r.asOf||'')} · ${esc(r.note||'')}</title></path>`}).join('');return `<svg class="network-svg" style="height:${height}px" viewBox="0 0 ${width} ${height}" role="img" aria-label="Typed GoTo investment and operating relationship network">${edges}${visible.map(e=>{const pos=positions.get(e.id);return `<g class="network-node ${e.id==='goto'?'core':''}" data-entity="${e.id}" tabindex="0" role="button" transform="translate(${pos.x},${pos.y-25})"><rect width="155" height="50" rx="7" ${/unresolved|historical|unverified/i.test(e.status)?'stroke-dasharray="4 3"':''}/><text x="12" y="21">${esc(e.name.length>23?e.name.slice(0,22)+'…':e.name)}</text><text class="node-subtitle" x="12" y="37">${e.stakePct!=null?`${e.stakePct}% effective · `:''}${esc(e.type.slice(0,28))}</text></g>`}).join('')}</svg>`}
function geography(nodes){const positions={Indonesia:[118,-2],Singapore:[103.82,1.35],Vietnam:[108,16],Philippines:[122,12],Malaysia:[102,4],Thailand:[101,15],'United States':[-100,39]};const countries=[...new Set(nodes.map(e=>e.country||'Not disclosed'))];const [west,east,south,north]=S.mapRegion==='world'?[-180,180,-60,85]:[90,142,-15,30],w=1100,h=520;const x=lon=>(lon-west)/(east-west)*w,y=lat=>(north-lat)/(north-south)*h;const shape=coords=>coords.map(ring=>ring.map(([lon,lat],i)=>`${i?'L':'M'}${x(lon).toFixed(1)},${y(lat).toFixed(1)}`).join(' ')+'Z').join(' ');const boundaries=(WORLD?.features||[]).map(f=>{const name=f.properties.name;const country=name==='Viet Nam'?'Vietnam':name;const active=countries.includes(country);let d=f.geometry.type==='Polygon'?shape(f.geometry.coordinates):f.geometry.type==='MultiPolygon'?f.geometry.coordinates.map(shape).join(' '):'';return `<path d="${d}" fill="${active?'#d6e7ce':'#e8eee4'}" stroke="#b8cdb0" stroke-width=".8"><title>${esc(name)}</title></path>`}).join('');const markers=countries.filter(c=>positions[c]).map(c=>{const [lon,lat]=positions[c],count=nodes.filter(e=>e.country===c).length;if(lon<west||lon>east||lat<south||lat>north)return '';const r=12+Math.min(10,count*.35);return `<g class="geo-marker" data-country="${esc(c)}" tabindex="0" role="button" transform="translate(${x(lon)},${y(lat)})"><circle r="${r+7}" fill="#477e5320"/><circle r="${r}" fill="${S.mapCountry===c?'#142f25':'#528553'}" stroke="#fff" stroke-width="2"/><text y="4" text-anchor="middle" fill="white" font-size="11" font-family="DM Sans">${count}</text><text y="${r+25}" text-anchor="middle" fill="#426d39" font-size="12" font-weight="600" font-family="DM Sans">${esc(c)}</text></g>`}).join('');const selected=S.mapCountry==='All'?nodes:nodes.filter(e=>e.country===S.mapCountry);return `<div class="geo-toolbar"><div class="segmented"><button data-georegion="sea" class="${S.mapRegion==='sea'?'active':''}">Southeast Asia</button><button data-georegion="world" class="${S.mapRegion==='world'?'active':''}">World</button></div><select id="geoCountry" class="filter-select"><option>All</option>${countries.map(c=>`<option ${S.mapCountry===c?'selected':''}>${esc(c)}</option>`).join('')}</select><span>Country-level context · ${nodes.filter(e=>e.country!=='Not disclosed').length} located entities</span></div><svg class="geographic-svg" viewBox="0 0 ${w} ${h}" role="img" aria-label="Geographic company ecosystem map"><defs><pattern id="geoGrid" width="25" height="25" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r=".5" fill="#c7d6be"/></pattern></defs><rect width="${w}" height="${h}" fill="#f2f7ee"/><rect width="${w}" height="${h}" fill="url(#geoGrid)"/>${boundaries}${markers}</svg><div class="geo-caption">Select a country to inspect its companies. Markers show country context, not exact office locations, market share or investment exposure. Unknown locations remain in the directory.</div><div class="geo-tray">${selected.map(entityNode).join('')}</div>`}
function ecosystem(){const nodes=mapNodes();return title('THE ECOSYSTEM EXPLORER','Map the relationships. Follow the exposure.','Explore operating businesses, legal subsidiaries, associates, fund relationships and portfolio companies. Select any entity to open its evidence.',`<button class="button" data-action="export-entities">${icon('download')}Export entities</button><button class="button primary" data-nav="portfolio">Portfolio & risk ${icon('arrow')}</button>`)+`<div class="filters"><input class="filter-input" id="mapSearch" type="search" placeholder="Company, capability or investment vehicle" value="${esc(S.mapQuery)}"><select class="filter-select" id="mapCategory">${['All','On-demand','Financial services','Strategic holdings','Venture network','Competitors','Sourcing universe'].map(x=>`<option ${x===S.mapType?'selected':''}>${x}</option>`).join('')}</select><div class="segmented">${[['landscape','Landscape'],['network','Ownership network'],['geography','World map']].map(([id,label])=>`<button class="${S.mapView===id?'active':''}" data-mapview="${id}">${label}</button>`).join('')}</div><span class="filter-count">${nodes.length} entities in this view</span></div><div class="ecosystem-stage" style="${S.mapView==='network'?'max-height:650px':''}">${S.mapView==='landscape'?landscape(nodes):S.mapView==='network'?network(nodes):geography(nodes)}</div><div class="map-key"><span>Source-backed relationship</span><span class="unresolved">Reported fund / historical link</span><span>Percentages show effective group holdings where disclosed</span></div><div class="coverage-callout">${icon('alert')}GoTo Ventures (legacy Tokopedia), Argor (formerly Go-Ventures) and Bintang Kecil are distinct records. Bintang Kecil’s historical Xurya / Laku6 investments and reported exits are distinct from Argor-managed fund exposure.</div><div class="card section-gap"><div class="card-head"><div><h2>Inside the ecosystem</h2><p>Each operating asset and investment link has its own news and monitoring questions</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Entity</th><th>Relationship</th><th>Effective stake</th><th>Evidence date / status</th><th>Monitoring focus</th></tr></thead><tbody>${nodes.filter(e=>e.id!=='goto').map(e=>`<tr><td><button class="table-company" data-entity="${e.id}">${companyLogo(e.name,e.id)}<span><b>${esc(e.name)}</b><small>${esc(e.sector)}</small></span></button></td><td>${esc(e.type)}</td><td>${e.stakePct!=null?fmt(e.stakePct,2)+'%':'Not disclosed / not applicable'}</td><td style="white-space:normal;min-width:160px">${esc(e.evidenceDate||e.status)}</td><td style="white-space:normal;min-width:220px">${esc(e.riskMonitor.trigger)}</td></tr>`).join('')}</tbody></table></div></div>`}
function portfolio(){const agg=D.portfolioAggregate, total=agg.categories.find(c=>c.label.includes('total')), ventures=agg.categories.find(c=>c.label==='Venture capital');const holdings=D.entities.filter(e=>['Associate','Indirect subsidiary','Argor-reported portfolio company','Independent fund manager / ecosystem link','Historically linked investee'].includes(e.type));return title('INVESTMENTS, OPERATIONS & LOOK-THROUGH','Portfolio & risk monitor','Follow ownership evidence, public business developments, aggregate carrying values and the questions missing from private-company reporting.',`<button class="button" data-action="export-portfolio">${icon('download')}Export monitoring list</button><button class="button primary" data-nav="ecosystem">Explore relationships ${icon('arrow')}</button>`)+`<div class="metric-grid">${metric('Other equity investments',`Rp${fmt(total.current/1e6,2)}tn`,'Aggregate carrying amount · 30 Jun 2026')}${metric('Venture-capital holdings',`Rp${fmt(ventures.current/1e6,2)}tn`,'Aggregate category · not Argor-specific NAV')}${metric('H1 fair-value adjustment',`−Rp${fmt(Math.abs(agg.fairValueAdjustmentH1)/1000,1)}bn`,'Aggregate adjustment · not a holding-level return','negative')}${metric('Portfolio news signals',fmt(D.events.filter(e=>e.category==='Portfolio news').length),'Product launches, partnerships & project milestones','','intelligence')}</div><div class="grid-2"><section class="card"><div class="card-head"><div><h2>Holdings and exposure register</h2><p>Public ownership evidence · private valuations remain undisclosed</p></div>${tag('30 Jun 2026 baseline','outline')}</div><div class="table-wrap"><table class="data-table"><thead><tr><th>Entity</th><th>Relationship</th><th>Group stake</th><th>Monitoring state</th></tr></thead><tbody>${holdings.map(e=>`<tr><td><button class="table-company" data-entity="${e.id}">${companyLogo(e.name,e.id)}<span><b>${esc(e.name)}</b><small>${esc(e.sector)}</small></span></button></td><td>${esc(e.type)}</td><td>${e.stakePct!=null?fmt(e.stakePct,2)+'%':'Not disclosed'}</td><td>${tag(e.stakePct!=null?'Ownership evidenced':'Look-through gap',e.stakePct!=null?'green':'amber')}</td></tr>`).join('')}</tbody></table></div></section><section class="card"><div class="card-head"><div><h2>Argor fund relationship</h2><p>Fund backing differs from direct startup ownership</p></div></div>${companyLogo('Argor Capital','argor')}<div class="detail-row"><span>Reported manager AUM</span><b>$${fmt(D.fund.managerAumUsd/1e6)}m</b></div><div class="detail-row"><span>Reported portfolio companies</span><b>${D.fund.reportedPortfolioCompanyCount}</b></div><div class="detail-row"><span>Examples mapped here</span><b>${D.entities.filter(e=>e.type==='Argor-reported portfolio company').length}</b></div><div class="detail-row"><span>GoTo commitment / allocation</span><b>Not disclosed</b></div><div class="detail-row"><span>GoTo attributable NAV / return</span><b>Not disclosed</b></div><div class="insight-box"><b>Exposure discipline</b>A manager's AUM and a portfolio funding round are not GoTo's invested capital. Request authorized fund reporting to assess NAV, distributions and look-through ownership.</div><button class="button" data-entity="argor" style="margin-top:18px;width:100%">Open fund evidence ↗</button></section></div><div class="card section-gap"><div class="card-head"><div><h2>Operating news from the venture network</h2><p>Public company mentions and business milestones · financial impact unquantified</p></div><button class="text-link" data-filter-news="Portfolio news">View in intelligence feed ↗</button></div><div class="news-grid">${D.events.filter(e=>e.category==='Portfolio news').map(eventCard).join('')}</div></div><div class="risk-grid section-gap">${[['Private-company disclosure','Moka and other subsidiaries have ownership evidence, but standalone revenue, retention and cash runway are not available in this dataset.','moka'],['Fund exposure visibility','Argor commitments, GoTo allocation, attributable NAV and fund returns require authorized reporting.','argor'],['Historical investment chain','Xurya has historical GoTo Ventures evidence; current stakes and the exact holding path remain unresolved.','xurya']].map(([name,desc,id])=>`<article class="card risk-card"><h3>${name}</h3><p>${desc}</p><div class="event-meta">${tag('Diligence question','amber')}<button class="text-link" data-entity="${id}">Open evidence ↗</button></div></article>`).join('')}</div>`}
function dealCard(o){return `<article class="deal-card"><h3>${companyLogo(o.name,o.id)}${esc(o.name)}</h3><p>${esc(o.fit)}</p><div class="business-tags">${tag(o.theme,'green')}${tag('Partner first','outline')}</div><div class="deal-actions"><select data-stage="${o.id}" aria-label="Pipeline stage for ${esc(o.name)}">${['Watchlist','Screening','Diligence','Deferred'].map(x=>`<option ${x===(stages[o.id]||o.stage)?'selected':''}>${x}</option>`).join('')}</select><button class="text-link" data-deal="${o.id}">View thesis ↗</button></div></article>`}
function deals(){const selected=D.opportunities.filter(o=>(S.dealFilter==='All'||o.theme===S.dealFilter)&&(!S.dealQuery||`${o.name} ${o.theme} ${o.country} ${o.profile}`.toLowerCase().includes(S.dealQuery.toLowerCase())));return title('STRATEGY → COUNTERPARTY → DILIGENCE','Deal sourcing radar','A researched counterparty universe for partnerships, investments and capability acquisition. Availability and valuation require diligence.',`<button class="button" data-action="export-deals">${icon('download')}Export pipeline</button><button class="button primary" data-nav="valuation">Test economics ${icon('arrow')}</button>`)+`<div class="filters"><input class="filter-input" id="dealSearch" placeholder="Search company, country or capability" value="${esc(S.dealQuery||'')}"><select class="filter-select" id="dealTheme">${['All',...new Set(D.opportunities.map(o=>o.theme))].map(x=>`<option ${x===S.dealFilter?'selected':''}>${x}</option>`).join('')}</select><span class="tag green">${selected.length} sourced company profiles</span><div class="segmented" style="margin-left:auto">${[['pipeline','Pipeline'],['list','Company database']].map(([id,label])=>`<button class="${S.dealView===id?'active':''}" data-dealview="${id}">${label}</button>`).join('')}</div></div>${S.dealView==='pipeline'?`<div class="pipeline">${['Watchlist','Screening','Diligence','Deferred'].map(stage=>`<div class="pipeline-column"><div class="pipeline-heading">${stage}<b>${selected.filter(o=>(stages[o.id]||o.stage)===stage).length}</b></div>${selected.filter(o=>(stages[o.id]||o.stage)===stage).map(dealCard).join('')||'<div class="empty" style="padding:30px 10px;font-size:10px">Move a researched company here when your review progresses.</div>'}</div>`).join('')}</div>`:`<div class="card"><div class="table-wrap"><table class="data-table"><thead><tr><th>Company</th><th>Country</th><th>Strategic theme</th><th>Stage</th><th>Profile sources</th><th>Review</th></tr></thead><tbody>${selected.map(o=>{const entity=D.entities.find(e=>e.id===o.id);return `<tr><td><button class="table-company" data-entity="${o.id}">${companyLogo(o.name,o.id)}<span><b>${esc(o.name)}</b><small>${esc(entity?.ownershipStatus||'Public profile')}</small></span></button></td><td>${esc(o.country)}</td><td>${esc(o.theme)}</td><td>${tag(stages[o.id]||o.stage,'outline')}</td><td><a class="text-link" href="${safeUrl(o.sourceUrl)}" target="_blank" rel="noopener">Company ↗</a>${entity?.crunchbase?` · <a class="text-link" href="${safeUrl(entity.crunchbase)}" target="_blank" rel="noopener">Crunchbase ↗</a>`:''}</td><td><button class="text-link" data-deal="${o.id}">Open thesis ↗</button></td></tr>`}).join('')}</tbody></table></div></div>`}<div class="coverage-callout">${icon('alert')}These are strategic screening hypotheses, not announced deals or companies known to be for sale. Existing capabilities—including Moka—are checked for overlap before an acquisition thesis.</div><div class="grid-3 section-gap">${[['Merchant enablement','Connect payments and merchant software to distribution, retention and consented lending data.','Moka / Midtrans / GoPay'],['Driver economics','Assess EV adoption, financing structure and driver total cost of ownership.','Mobility ecosystem'],['Logistics capability','Compare service density, fulfillment economics and integration complexity.','On-demand delivery']].map(([name,desc,link])=>`<article class="card"><div class="eyebrow">STRATEGIC THEME</div><h3>${name}</h3><p class="tiny muted" style="margin-top:10px">${desc}</p><div class="business-tags" style="margin-top:15px">${tag(link,'outline')}</div></article>`).join('')}</div>`}
function competitors(){const gotoRevenue=gotoMetric('netRevenue');return title('COMPETITIVE INTELLIGENCE','GoTo, Grab and Sea. Side by side.','Financial disclosure, business moves and product footprint—preserving segment definitions, currencies and geographic scope.')+`<div class="company-metrics">${[{id:'goto',name:'GoTo Group',ticker:'GOTO',rev:`Rp${fmt(gotoRevenue.value/1000,2)}tn`,revYoY:31,eb:`Rp${fmt(gotoMetric('adjustedEbitda').value)}bn`,scope:'Indonesia-led ecosystem',url:'https://gotocompany.com/investor-relations/en',businesses:['Gojek','GoPay','Merchant tools']},...D.companies.map(c=>({id:c.id,name:c.name,ticker:c.ticker,rev:`$${fmt(competitorMetric(c.id,'Revenue').value/1000,2)}bn`,revYoY:competitorMetric(c.id,'Revenue').yoy_pct,eb:`$${fmt(competitorMetric(c.id,'Adjusted EBITDA').value)}m`,scope:c.scope,url:c.ir_url,businesses:c.businesses}))].map(c=>`<article class="card company-card"><div class="company-card-head">${companyLogo(c.name,c.id)}<div><h2>${esc(c.name)}</h2><small>${c.ticker} · Q2 2026</small></div></div><div class="metric-label">Reported revenue</div><div class="metric-value">${c.rev}</div><div class="metric-foot">${tag('+'+fmt(c.revYoY,1)+'% YoY','green')} ${esc(c.scope)}</div><div class="horizontal-rule"></div><div class="detail-row"><span>Adjusted EBITDA</span><b>${c.eb}</b></div><div class="business-tags">${c.businesses.map(b=>tag(b)).join('')}</div><a class="button" style="width:100%;margin-top:20px" href="${safeUrl(c.url)}" target="_blank" rel="noopener">Investor relations ↗</a></article>`).join('')}</div><div class="coverage-callout">${icon('alert')}Group revenues are in different currencies and cover different businesses and geographies. These values are not Indonesia market shares. Adjusted EBITDA definitions differ by issuer.</div><section class="card"><div class="card-head"><div><h2>Competitive footprint</h2><p>Product and segment coverage, rather than unsupported market-share rankings</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Capability</th><th>GoTo ecosystem</th><th>Grab ecosystem</th><th>Sea ecosystem</th></tr></thead><tbody>${D.competitiveMatrix.map(r=>`<tr><td><b>${esc(r.segment)}</b></td><td>${esc(r.goto)}</td><td>${esc(r.grab)}</td><td>${esc(r.sea)}</td></tr>`).join('')}</tbody></table></div></section><section class="card section-gap"><div class="card-head"><div><h2>Business and corporate developments</h2><p>Results, acquisitions, banking consolidation and funding</p></div></div><div class="news-grid">${D.events.filter(e=>e.category==='Competitor').map(eventCard).join('')}</div></section><section class="card section-gap"><div class="card-head"><div><h2>Financial disclosure detail</h2><p>Actuals and guidance kept distinct; source definitions preserved</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Company</th><th>Metric</th><th>Scope</th><th>Value</th><th>Period</th><th>Basis</th></tr></thead><tbody>${D.competitorMetrics.map(m=>`<tr><td>${esc(m.company_id.toUpperCase())}</td><td>${esc(m.label)}${m.note?`<small style="display:block;white-space:normal;max-width:300px;margin-top:4px;color:#96a48d">${esc(m.note)}</small>`:''}</td><td>${esc(m.scope)}</td><td>${Array.isArray(m.value)?m.value.map(v=>fmt(v)).join('–'):fmt(m.value,m.value<10?1:0)} ${esc(m.unit)}</td><td>${esc(m.period)}</td><td>${tag(m.kind==='management_guidance'?'Guidance':'Reported',m.kind==='management_guidance'?'amber':'green')}</td></tr>`).join('')}</tbody></table></div></section>`}
function brokerResearch(){return title('ATTRIBUTED RESEARCH & EXPECTATIONS','Research library','Collect report vintages, compare forecast changes and keep broker opinions separate from company disclosures and your own assumptions.',`<button class="button" data-action="export-reports">${icon('download')}Export report index</button>`)+`<div class="grid-3">${D.reports.map(r=>`<article class="card report-card"><div class="report-cover"><small>${esc(r.publisher)}</small><strong>GOTO · Company update</strong><span class="cover-date">${date(r.report_date)}</span></div><div class="event-meta">${tag('Historical report','outline')}<span>${date(r.report_date)}</span></div><h3>${esc(r.title)}</h3><div class="report-stats"><div><small>RATING</small><b>${esc(r.rating)}</b></div><div><small>TARGET PRICE</small><b>Rp${r.target_price_idr}</b></div><div><small>PREVIOUS TARGET</small><b class="muted">Rp${r.previous_target_price_idr}</b></div></div><p>${esc(r.rating_action)} rating · ${esc(r.valuation_method_reported)} valuation · tactical ${esc(r.tactical_rating)}</p><div class="card-head"><button class="text-link" data-report="${r.id}">Read analysis ↗</button><a class="text-link" href="${safeUrl(r.sourceUrl)}" target="_blank" rel="noopener">Original PDF ↗</a></div></article>`).join('')}<article class="card"><div class="eyebrow">OBSERVED BROKER VINTAGES</div><h2>Targets changed. So did assumptions.</h2><div class="revision-chart">${D.reports.map(r=>`<div class="revision-bar" style="height:${r.target_price_idr*1.3}px"><b>Rp${r.target_price_idr}</b><small>${date(r.report_date)}</small></div>`).join('')}</div><p class="chart-note">Two collected BRIDS vintages; intervening publications may exist. Historical targets are not today's fair value or a complete broker consensus.</p></article></div><section class="card section-gap"><div class="card-head"><div><h2>Forecast comparison</h2><p>BRIDS forecasts · IDR billion · distinct financial and adjusted measures</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Report date</th><th>Forecast year</th><th>Net revenue</th><th>EBITDA</th><th>Adjusted EBITDA</th><th>Net profit</th><th>EPS · Rp</th></tr></thead><tbody>${D.reports.flatMap(r=>r.forecasts.map(f=>`<tr><td>${date(r.report_date)}</td><td>${f.year}F</td><td>${fmt(f.group_net_revenue)}</td><td>${fmt(f.ebitda_income_statement)}</td><td>${f.group_adjusted_ebitda!=null?fmt(f.group_adjusted_ebitda):'Not normalized'}</td><td>${fmt(f.net_profit)}</td><td>${fmt(f.eps,1)}</td></tr>`)).join('')}</tbody></table></div></section><div class="coverage-callout">${icon('alert')}Report quality checks flag mismatched revision ranges and separate EBITDA from adjusted EBITDA. The library contains authorized public reports; it does not claim complete broker coverage.</div>`}
function research(){if(S.researchTab==='goto')return brokerResearch()+`<button class="button section-gap" data-researchtab="all">← All research & market reports</button>`;const records=D.researchLibrary||[];const categories=['All',...new Set(records.map(r=>r.category))];const term=(S.researchQuery||'').toLowerCase();const filtered=records.filter(r=>(!S.researchCategory||S.researchCategory==='All'||r.category===S.researchCategory)&&`${r.title} ${r.publisher} ${r.category} ${(r.topics||[]).join(' ')}`.toLowerCase().includes(term));const featured=filtered.filter(r=>r.reviewed).slice(0,8);return title('EQUITY · ECONOMICS · M&A · PRIVATE CAPITAL','Research & report library','Explore the full Cockpit research index, reviewed PDF briefs and company reports. Summaries distinguish inspected evidence from archived discovery metadata.',`<button class="button" data-researchtab="goto">GOTO equity research ↗</button>`)+`<div class="metric-grid">${metric('Cockpit indexed reports',fmt(records.length),'Archived index · 13 Sep 2026 baseline','','research')}${metric('Reviewed research PDFs',fmt(records.filter(r=>r.reviewed).length),'Executive / overview sections reviewed','','research')}${metric('GOTO broker vintages',fmt(D.reports.length),'Dated forecasts, ratings and target revisions','','markets')}${metric('Research categories',fmt(categories.length-1),'Macro, credit, equity, markets and private capital','','ecosystem')}</div><div class="filters"><input class="filter-input" id="researchSearch" type="search" placeholder="Search M&A, market conditions, publisher or company" value="${esc(S.researchQuery||'')}"><select class="filter-select" id="researchCategory">${categories.map(c=>`<option ${c===(S.researchCategory||'All')?'selected':''}>${esc(c)}</option>`).join('')}</select><span class="filter-count">${filtered.length} matching reports</span></div>${featured.length?`<div class="grid-3">${featured.map(r=>`<article class="card report-card"><div class="report-cover"><small>${esc(r.publisher)}</small><strong>${esc(r.category.replace(' & ',' / '))}</strong><span class="cover-date">${date(r.date)}</span></div><div class="event-meta">${tag('Reviewed PDF brief','green')}<span>${date(r.date)}</span></div><h3>${esc(r.title)}</h3><p style="margin-top:12px">${esc(r.summary)}</p><div class="business-tags" style="margin-top:15px">${(r.topics||[r.geography]).slice(0,3).map(t=>tag(t,'outline')).join('')}</div><div class="card-head"><button class="text-link" data-research="${r.id}">Read summary ↗</button><a class="text-link" href="${safeUrl(r.pdfUrl||r.url)}" target="_blank" rel="noopener">Original PDF ↗</a></div></article>`).join('')}</div>`:''}<section class="card section-gap"><div class="card-head"><div><h2>Complete research index</h2><p>Publisher, reporting vintage, geography, access and summary readiness</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Report</th><th>Publisher</th><th>Category</th><th>Vintage</th><th>Summary evidence</th><th>Original resource</th></tr></thead><tbody>${filtered.map(r=>`<tr><td style="white-space:normal;min-width:260px;max-width:340px"><button class="text-link" style="text-align:left;white-space:normal;line-height:1.7" data-research="${r.id}">${esc(r.title)}</button><small style="display:block;color:#95a586;margin-top:4px">${esc(r.geography||'Region not supplied')}</small></td><td>${esc(r.publisher)}</td><td>${esc(r.category)}</td><td>${date(r.date)}</td><td>${tag(r.reviewed?'Reviewed sections':'Discovery metadata',r.reviewed?'green':'outline')}</td><td><a class="text-link" href="${safeUrl(r.pdfUrl||r.indexedPdfUrl||r.url)}" target="_blank" rel="noopener">${r.pdfUrl?'Verified PDF':r.indexedPdfUrl?'Indexed PDF':'Publisher page'} ↗</a></td></tr>`).join('')}</tbody></table></div></section><div class="coverage-callout">${icon('alert')}The 233-record index is a dated Cockpit archive, not a claim of current comprehensive coverage. Reviewed briefs summarize selected report sections. Unread records retain their source links without invented report conclusions.</div>`}
function openResearch(id){const r=D.researchLibrary.find(r=>r.id===id);if(!r)return;openDrawer(`<div class="eyebrow">${esc(r.category)} · ${date(r.date)}</div><h2>${esc(r.title)}</h2><p class="drawer-subtitle">${esc(r.publisher)} · ${esc(r.geography||'Global context')}</p><div class="business-tags" style="margin-top:16px">${tag(r.reviewed?'Reviewed primary PDF':'Archived discovery record',r.reviewed?'green':'amber')}</div><div class="drawer-section"><h3>Evidence scope</h3><p>${esc(r.summaryBasis)}</p>${r.evidenceScope?`<p>${esc(r.evidenceScope)}</p>`:''}</div>${r.reviewed?`<div class="drawer-section"><h3>Research summary</h3><p>${esc(r.summary)}</p></div><div class="drawer-section"><h3>Key takeaways</h3><ul>${(r.takeaways||[]).map(t=>`<li>${esc(t)}</li>`).join('')}</ul></div><div class="drawer-section"><h3>Implications for GoTo · analyst interpretation</h3><p>${esc(r.implication)}</p></div>`:`<div class="drawer-section"><h3>Summary readiness</h3><p>The full report has not been inspected in this workspace. This record supports discovery, not a report-content summary. Open the publisher document before relying on its conclusions.</p></div>`}<div class="drawer-section"><h3>Original source</h3>${sourceLink(r.pdfUrl||r.indexedPdfUrl||r.url,r.pdfUrl?'Verified original PDF':r.indexedPdfUrl?'Indexed PDF link · access not rechecked':'Official publisher resource')}<p class="tiny muted">${esc(r.access||'Access status not supplied')}${r.reviewedOn?' · reviewed '+date(r.reviewedOn):' · index baseline September 2026'}</p></div>${noteSection('research-'+id)}`)}
function ir(){const docs=D.documents.filter(d=>(S.docFilter==='All'||d.category===S.docFilter)&&`${d.title} ${d.company} ${d.category}`.toLowerCase().includes(S.docQuery.toLowerCase()));return title('OFFICIAL DISCLOSURE HUB','Investor relations, in one place.','Earnings, presentations, statements, transcripts, corporate actions, ownership and governance—linked directly to official issuer resources.',`<a class="button primary" href="https://gotocompany.com/investor-relations/en" target="_blank" rel="noopener">GoTo investor relations ${icon('external')}</a>`)+`<div class="ir-links">${[['GoTo investor relations','Financial information, shareholders, meetings and official disclosures.','https://gotocompany.com/investor-relations/en'],['Grab investor relations','Quarterly results and regional operating disclosures.','https://investors.grab.com'],['Sea investor relations','Shopee, Monee, Garena and group results.','https://www.sea.com/investor/home']].map(([name,desc,url])=>`<a class="ir-link" href="${url}" target="_blank" rel="noopener"><h3>${name} ↗</h3><p>${desc}</p>${tag('Official issuer website','green')}</a>`).join('')}</div><div class="tabs-line section-gap"><button class="active">Document library</button><button data-action="open-ownership">Shareholder snapshot ↗</button><button data-action="corporate-timeline">Corporate-action timeline ↗</button></div><div class="filters"><input class="filter-input" id="docSearch" placeholder="Search results, reports or meeting materials" value="${esc(S.docQuery)}"><select class="filter-select" id="docCategory">${['All',...new Set(D.documents.map(d=>d.category))].map(x=>`<option ${x===S.docFilter?'selected':''}>${esc(x)}</option>`).join('')}</select><span class="filter-count">${docs.length} official links</span></div><div class="document-list">${docs.map(d=>`<a class="document" href="${safeUrl(d.url)}" target="_blank" rel="noopener"><div class="document-icon">${d.url.toLowerCase().includes('.pdf')?'PDF':d.category==='Transcript'?'TXT':'IR'}</div><div><h3>${esc(d.title)}</h3><small>${esc(d.company)} · ${esc(d.category)} · ${d.date?date(d.date):'Official directory'}</small></div><span>↗</span></a>`).join('')}</div><p class="chart-note">Directory links are verified discovery records. Full document content is marked reviewed only when inspected. All financial metrics retain their reporting period.</p><section class="card section-gap"><div class="card-head"><div><h2>GoTo financial trajectory</h2><p>Official consolidated quarterly flows · IDR billion</p></div></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Period</th><th>Net revenue</th><th>Adjusted EBITDA</th><th>Profit / loss for period</th><th>Calculation basis</th></tr></thead><tbody>${D.quarterly.map(q=>`<tr><td>${q.period}</td><td>${fmt(q.netRevenue)}</td><td>${fmt(q.adjustedEbitda)}</td><td class="${q.netProfit>=0?'positive':'negative'}">${fmt(q.netProfit)}</td><td style="white-space:normal">${esc(q.basis)}</td></tr>`).join('')}</tbody></table></div></section>`}
function acquisitionLab(){return title('TRANSPARENT ASSUMPTIONS','Valuation & capital allocation lab','Test an acquisition scenario, inspect the enterprise-to-equity bridge, and compare it with capital-allocation priorities.')+`<div class="coverage-callout">${icon('alert')}This is an illustrative acquisition model, not a valuation of GoTo or a sourced price for a private company. Adjust the inputs; all values are IDR billion.</div><div class="model-grid"><section class="card"><div class="card-head"><div><h2>Acquisition assumptions</h2><p>Deterministic calculations · editable scenario inputs</p></div></div>${[['modelEbitda','Standalone EBITDA',150,10,1000,10,'bn'],['modelMultiple','Entry EV / EBITDA',8,2,20,.5,'×'],['modelSynergy','Annual EBITDA synergy',30,0,250,5,'bn'],['modelCost','One-off integration cost',100,0,1000,25,'bn'],['modelDebt','Target net debt',100,-500,1000,25,'bn']].map(([id,label,value,min,max,step,unit])=>`<div class="model-field"><label for="${id}">${label}<b id="${id}Value">${value}${unit==='×'?'×':' bn'}</b></label><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}" data-model></div>`).join('')}<div class="insight-box"><b>Committee questions</b>Which synergies are achievable? Who owns delivery? What is the downside case? What competing use of capital should we compare?</div></section><section><div class="model-result"><div class="eyebrow">CALCULATED ENTERPRISE VALUE</div><div class="metric-value" id="modelEV">Rp1,200bn</div><p>Standalone EBITDA × selected entry multiple</p><div class="horizontal-rule"></div><div class="detail-row"><span>Less target net debt</span><b id="modelNetDebt">Rp100bn</b></div><div class="detail-row"><span>Implied equity consideration</span><b id="modelEquity">Rp1,100bn</b></div><div class="detail-row"><span>Integration cost</span><b id="modelIntegration">Rp100bn</b></div><div class="detail-row"><span>Equity payment + integration</span><b id="modelFunding">Rp1,200bn</b></div><div class="horizontal-rule"></div><div class="detail-row"><span>EV + integration / post-synergy EBITDA</span><b id="modelEffective">7.22×</b></div><div class="detail-row"><span>Simple integration payback from synergy</span><b id="modelPayback">3.33 years</b></div><p class="tiny">Payback ignores tax, timing, cash conversion and execution risk. Not an IRR or NPV. Target net debt treatment depends on transaction structure.</p></div><section class="card section-gap"><div class="card-head"><h2>GoTo capital-allocation context</h2></div><div class="detail-row"><span>FY2026 group EBITDA guidance</span><b>Rp3.2–3.4tn</b></div><div class="detail-row"><span>Fintech guidance</span><b>Rp1.7–1.8tn</b></div><div class="detail-row"><span>ODS guidance</span><b>Rp1.4–1.5tn</b></div><p class="chart-note">Management guidance as of 29 July 2026, not an acquisition budget or available cash. Assess financing and balance-sheet constraints separately.</p></section></section></div>`}
function navigation(){const groups={0:'OVERVIEW',3:'GOTO',6:'ECOSYSTEM',9:'DEALS & RESEARCH',13:'SYSTEM'};$('#navigation').innerHTML=NAV.map(([id,label,ico],i)=>`${groups[i]?`<div class="nav-section">${groups[i]}</div>`:''}<a href="#${id}" class="nav-item ${view===id?'active':''}" aria-current="${view===id?'page':'false'}">${icon(ico)}<span>${label}</span>${['ecosystem','research'].includes(id)?`<span class="nav-badge">${id==='ecosystem'?D.entities.length:D.researchLibrary.length}</span>`:''}</a>`).join('');$('#breadcrumb').textContent=NAV.find(x=>x[0]===view)?.[1]||'Decision brief'}
function render(keepScroll=false){if(!D)return;let scroll=window.scrollY;view=location.hash.slice(1)||'overview';if(!NAV.some(n=>n[0]===view))view='overview';navigation();const renderers={overview,markets,economics,financials,actions,system,intelligence,ecosystem,portfolio,deals,competitors,research,'investor-relations':ir,valuation};$('#main').innerHTML=renderers[view]();document.title=NAV.find(x=>x[0]===view)[1]+' · GoTo Strategic Intelligence';bindView();if(view==='markets'&&$('#liveChart'))loadTradingView(asset(S.market));if(view==='ecosystem'&&S.mapView==='geography'&&!WORLD)fetch('data/world.geojson').then(r=>r.json()).then(d=>{WORLD=d;if(view==='ecosystem'&&S.mapView==='geography')render(true)}).catch(()=>toast('Map boundaries unavailable; company directory remains available.'));if(!keepScroll)window.scrollTo(0,0);else window.scrollTo(0,scroll);$('#sidebar').classList.remove('mobile-open')}
function loadTradingView(a){const el=$('#liveChart');if(!el)return;const wrap=document.createElement('div');wrap.className='tradingview-widget-container';wrap.innerHTML='<div class="tradingview-widget-container__widget"></div><div class="tradingview-widget-copyright"><a href="'+safeUrl(a.providerChartUrl)+'" target="_blank" rel="noopener">Chart by TradingView ↗</a></div>';const script=document.createElement('script');script.src='https://s3.tradingview.com/external-embedding/embed-widget-advanced-chart.js';script.async=true;script.textContent=JSON.stringify({autosize:true,symbol:a.tradingViewSymbol,interval:'D',timezone:'Asia/Jakarta',theme:'light',style:'1',locale:'en',allow_symbol_change:true,calendar:false,hide_side_toolbar:false,support_host:'https://www.tradingview.com'});script.onerror=()=>{el.innerHTML=`<div class="empty">The provider chart could not load.<br><a class="source-link" target="_blank" rel="noopener" href="${safeUrl(a.providerChartUrl)}">Open ${a.ticker} on TradingView ↗</a></div>`};wrap.appendChild(script);el.replaceChildren(wrap)}
function openDrawer(html){$('#drawerBody').innerHTML=html;$('#drawerBackdrop').hidden=false;$('#drawer').classList.add('open');$('#drawer').setAttribute('aria-hidden','false');$('#drawer').inert=false;$('#drawerClose').focus();document.body.style.overflow='hidden';bindDrawer()}
function closeDrawer(){ $('#drawerBackdrop').hidden=true;$('#drawer').classList.remove('open');$('#drawer').setAttribute('aria-hidden','true');$('#drawer').inert=true;document.body.style.overflow='';}
function noteSection(id){return `<div class="drawer-section"><h3>Your diligence notes</h3><textarea id="diligenceNote" placeholder="Add questions, assumptions or follow-up work…">${esc(notes[id]||'')}</textarea><button class="button" data-note-save="${id}">Save notes in this browser</button></div>`}
function companyDetails(e){const m=e.market||{},v=e.verification||{},leader=e.leader||{},hq=e.headquarters||{};return `<div class="drawer-section"><h3>Company details & market profiles</h3><div class="detail-row"><span>Country context</span><b>${esc(e.country||hq.country||'Not verified')}</b></div>${e.countryBasis?`<p class="tiny muted">${esc(e.countryBasis.replaceAll('_',' '))}</p>`:''}<div class="detail-row"><span>Founded</span><b>${e.foundedYear||'Not verified'}</b></div><div class="detail-row"><span>Leadership</span><b>${esc(leader.name||'Not verified')}</b></div><div class="detail-row"><span>Public / private</span><b>${esc(e.ownershipStatus||m.type||'Not verified')}</b></div><div class="detail-row"><span>Latest funding round</span><b>${m.latestRoundAmountUsd!=null?'$'+fmt(m.latestRoundAmountUsd/1e6,1)+'m':'Not disclosed / not verified'}</b></div><div class="detail-row"><span>Funding vintage</span><b>${m.latestRoundDate?date(m.latestRoundDate):'Not verified'}</b></div><div class="detail-row"><span>Private valuation</span><b>${m.latestValuationUsd!=null?'$'+fmt(m.latestValuationUsd/1e6,1)+'m':'Not disclosed / not verified'}</b></div>${sourceLink(e.website,'Official website')}${sourceLink(m.crunchbase||e.crunchbase,'Verified Crunchbase profile')}${sourceLink(m.dealroom||e.dealroom,'Verified Dealroom profile')}${sourceLink(e.linkedin,'Company LinkedIn')}${sourceLink(D.logos?.[e.id]?.officialWebsite||e.logoSourceUrl,'Brand asset provenance')}<p class="tiny muted">${esc(e.profileBasis||'Source-backed ecosystem record')}${(e.lastVerifiedAt||v.lastVerifiedAt)?' · saved verification '+date(e.lastVerifiedAt||v.lastVerifiedAt):''}. Saved profile details require current confirmation before a transaction decision.</p></div>`}
function openEntity(id){const e=D.entities.find(e=>e.id===id);if(!e)return;const relationships=D.relationships.filter(r=>r.to===id||r.from===id),events=D.events.filter(n=>n.company.toLowerCase().includes(e.name.toLowerCase())||n.tags.some(t=>t.toLowerCase()===e.name.toLowerCase()));openDrawer(`${companyLogo(e.name,e.id)}<div class="eyebrow" style="margin-top:20px">${esc(e.category)}</div><h2>${esc(e.name)}</h2><p class="drawer-subtitle">${esc(e.legalName||e.description||e.sector)}</p><div class="business-tags" style="margin-top:14px">${tag(e.type,'green')}${tag(e.stakePct!=null?e.stakePct+'% effective':'Stake not disclosed / not applicable','outline')}</div><div class="drawer-section"><h3>Evidence & relationship</h3><p>${esc(e.status)}</p>${sourceLink(e.sourceUrl,'Source supporting this relationship')}${relationships.map(r=>`<div class="detail-row"><span>${esc(D.entities.find(x=>x.id===r.from)?.name||r.from)} → ${esc(D.entities.find(x=>x.id===r.to)?.name||r.to)}</span><b>${esc(r.type)}${r.stakePct!=null?' · '+r.stakePct+'%':''}</b></div>${r.note?`<p class="tiny muted">${esc(r.note)}</p>`:''}`).join('')}</div><div class="drawer-section"><h3>Performance visibility</h3><p>${esc(e.riskMonitor.visibility)}</p>${e.id==='argor'?`<div class="detail-row"><span>Reported manager AUM</span><b>$${fmt(D.fund.managerAumUsd/1e6)}m</b></div><p class="tiny muted">Manager profile statistic; not GoTo exposure or return.</p>`:''}</div><div class="drawer-section"><h3>What to monitor next</h3><p>${esc(e.riskMonitor.trigger)}</p></div>${events.length?`<div class="drawer-section"><h3>Related business updates</h3>${events.map(eventRow).join('')}</div>`:''}${companyDetails(e)}${noteSection(id)}`)}
function openEvent(id){const e=D.events.find(e=>e.id===id);if(!e)return;openDrawer(`<div class="eyebrow">${esc(e.category)} · ${date(e.date)}</div><h2>${esc(e.title)}</h2><div class="business-tags">${tag(e.company,'green')}${tag(e.status,'outline')}</div><div class="drawer-section"><h3>Observed evidence</h3><p>${esc(e.summary)}</p>${sourceLink(e.sourceUrl,e.publisher+' · original source')}<p class="tiny muted">Evidence scope: ${esc(e.evidence)}</p></div><div class="drawer-section"><h3>Corporate-development implication</h3><div class="implication-chain"><div class="chain-step"><b>What changed</b>${esc(e.summary)}</div><div class="chain-step"><b>Why it may matter · analyst interpretation</b>${esc(e.implication)}</div><div class="chain-step"><b>Next evidence or action</b>${esc(e.nextAction)}</div></div></div><div class="drawer-section"><h3>Evidence discipline</h3><p>Publication date, action status and reporting scope are preserved. Financial impact is not quantified unless the source provides it. Public announcements do not establish private investment returns.</p></div>${noteSection(id)}<button class="button" data-save="${id}">${saved.includes(id)?'★ Saved · remove':'☆ Save to your review list'}</button>`)}
function openDeal(id){const o=D.opportunities.find(o=>o.id===id);openDrawer(`${companyLogo(o.name,o.id)}<div class="eyebrow" style="margin-top:20px">SOURCED COUNTERPARTY · ${esc(o.country)}</div><h2>${esc(o.name)}</h2><p class="drawer-subtitle">${esc(o.profile)}</p><div class="business-tags" style="margin-top:15px">${tag(o.theme,'green')}${tag(stages[id]||'Watchlist','outline')}</div><div class="drawer-section"><h3>Strategic fit · screening hypothesis</h3><p>${esc(o.fit)}</p><div class="detail-row"><span>Suggested route</span><b>${esc(o.route)}</b></div><div class="detail-row"><span>Transaction availability</span><b>Unknown</b></div><div class="detail-row"><span>Revenue / valuation</span><b>Not disclosed</b></div></div><div class="drawer-section"><h3>Existing capability overlap</h3><p>${esc(o.overlap)}</p></div><div class="drawer-section"><h3>Diligence questions</h3><ul>${o.diligence_questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div><div class="drawer-section"><h3>Research evidence</h3>${sourceLink(o.sourceUrl,'Official company profile')}<p>${esc(o.availability)}</p></div>${companyDetails(D.entities.find(e=>e.id===id)||{})}${noteSection('deal-'+id)}`)}
function openReport(id){const r=D.reports.find(r=>r.id===id);openDrawer(`<div class="eyebrow">${esc(r.publisher)} · ${date(r.report_date)}</div><h2>${esc(r.title)}</h2><div class="business-tags">${tag(r.rating,'green')}${tag('Historical broker opinion','outline')}</div><div class="detail-stat-grid" style="margin-top:22px"><div class="detail-stat"><small>TARGET PRICE</small><b>Rp${r.target_price_idr}</b></div><div class="detail-stat"><small>PREVIOUS TARGET</small><b>Rp${r.previous_target_price_idr}</b></div></div><div class="drawer-section"><h3>Rating & valuation basis</h3><div class="detail-row"><span>Tactical rating / horizon</span><b>${r.tactical_rating} / ${r.tactical_horizon_months} months</b></div><div class="detail-row"><span>Valuation method</span><b>${r.valuation_method_reported}</b></div><div class="detail-row"><span>Historical reference price</span><b>Rp${r.reference_price_idr}</b></div><p class="tiny muted">Report reference price and target are historical. They are not today's stock quote or the dashboard's recommendation.</p></div><div class="drawer-section"><h3>Quality and interpretation checks</h3><ul>${r.quality_flags.map(q=>`<li>${esc(q)}</li>`).join('')}</ul></div><div class="drawer-section"><h3>Original report</h3>${sourceLink(r.sourceUrl,'Read authorized public PDF')}</div>${noteSection(id)}`)}
function methodology(){openDrawer(`<div class="eyebrow">HOW TO READ THIS WORKSPACE</div><h2>Evidence before opinion.</h2><p class="drawer-subtitle">A public-data corporate-development research workspace, independently built for an interview demonstration.</p><div class="drawer-section"><h3>Four kinds of information</h3><ul><li>Reported company facts and official statistical releases retain dates, units and scope.</li><li>Broker forecasts and ratings are attributed opinions.</li><li>Calculations use visible inputs and consistent definitions.</li><li>Strategic implications and sourcing ideas are analyst interpretations.</li></ul></div><div class="drawer-section"><h3>Monitoring & updates</h3><p>Research dataset compiled 13 October 2026. Interactive charts load directly from TradingView. The IDX quote button retrieves a provider snapshot. The weekly Monday 08:00 WIB chat monitor is separate; this website's curated research dataset is a dated compilation.</p></div><div class="drawer-section"><h3>Investment relationships</h3><p>Operating products, legal ownership, fund backing and historical investments have different relationship types. Private financials, GoTo fund exposure and attributable returns remain undisclosed unless evidenced.</p></div><div class="drawer-section"><h3>Your workspace</h3><p>Saved updates, deal stages and notes are kept in this browser. Export them for sharing or retention. The dashboard does not send outreach or execute transactions.</p></div>`)}
function openSources(){openDrawer(`<div class="eyebrow">SOURCE REGISTER</div><h2>Evidence & coverage</h2><p class="drawer-subtitle">${D.entities.length} entities · ${D.events.length} dated updates · ${D.documents.length} official document links · ${D.reports.length} broker reports.</p><div class="drawer-section"><h3>Sources</h3>${allSources().map((s,i)=>`<a class="source-item" href="${safeUrl(s.url)}" target="_blank" rel="noopener"><span class="source-num">${i+1}</span><div><h3>${esc(s.title)}</h3><p>${esc(s.publisher||new URL(s.url).hostname)}${s.date?' · '+date(s.date):''}</p></div><span>↗</span></a>`).join('')}</div><div class="drawer-section"><h3>Coverage limitations</h3><ul>${D.coverage.limitations.filter((v,i,a)=>a.indexOf(v)===i).map(v=>`<li>${esc(v)}</li>`).join('')}</ul></div>`)}
function openOwnership(){openDrawer(`<div class="eyebrow">GOTO SHAREHOLDER INFORMATION</div><h2>Ownership snapshot</h2><p class="drawer-subtitle">Official snapshot as of ${date(D.ownership.asOf)}. Later changes are not automatically reconciled.</p><div class="drawer-section"><h3>Reported capital</h3><div class="detail-row"><span>Total issued shares</span><b>${fmt(D.ownership.totalIssued)}</b></div><div class="detail-row"><span>Treasury shares</span><b>${fmt(D.ownership.treasury)}</b></div><div class="detail-row"><span>Foreign ownership</span><b>${fmt(D.ownership.foreignPct,2)}%</b></div>${D.ownership.holders.map(h=>`<div class="detail-row"><span>${esc(h.name)}</span><b>${fmt(h.pct,2)}%</b></div>`).join('')}${sourceLink(D.ownership.sourceUrl,'Official ownership disclosure')}</div><div class="drawer-section"><h3>Corporate-action follow-up</h3><p>${esc(D.ownership.warning)}</p><p>Reconcile issued, treasury, outstanding and diluted shares before calculating per-share effects. Cancellation does not automatically create new cash or a mechanical valuation uplift.</p></div>`)}
function timeline(){openDrawer(`<div class="eyebrow">GOTO CORPORATE ACTIONS</div><h2>Action status, in context.</h2><div class="drawer-section"><div class="timeline-line">${D.events.filter(e=>e.company==='GoTo').map(e=>`<article class="timeline-event" data-event="${e.id}" tabindex="0" role="button"><small>${date(e.date)} · ${esc(e.status)}</small><h3>${esc(e.title)}</h3><p>${esc(e.summary)}</p></article>`).join('')}</div></div>`)}
function openSaved(){openDrawer(`<div class="eyebrow">YOUR REVIEW LIST</div><h2>Saved intelligence</h2><p class="drawer-subtitle">Stored in this browser.</p><div class="drawer-section">${D.events.filter(e=>saved.includes(e.id)).map(eventRow).join('')||'<p>No saved updates yet. Use the star on a news card to add one.</p>'}</div><button class="button" data-action="export-saved">${icon('download')}Export saved updates & notes</button>`)}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200)}
function save(id){saved=saved.includes(id)?saved.filter(x=>x!==id):[...saved,id];persist();toast(saved.includes(id)?'Saved to your review list':'Removed from saved items');if($('#drawer').classList.contains('open')){const b=$(`[data-save="${id}"]`);if(b)b.textContent=saved.includes(id)?'★ Saved · remove':'☆ Save to your review list'}else render(true)}
function download(filename,contents,type='text/plain'){const blob=new Blob([contents],{type}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);toast('Export downloaded')}
function csv(rows){if(!rows.length)return '';const keys=Object.keys(rows[0]),encode=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replaceAll('"','""')+'"';return [keys.map(encode).join(','),...rows.map(r=>keys.map(k=>encode(r[k])).join(','))].join('\n')}
function exportAction(action){if(action==='export-brief'){download('GoTo-strategic-intelligence-brief.md',`# GoTo Strategic Intelligence\n\nResearch compilation: ${D.asOf}\n\n## Recent updates\n\n`+D.events.slice(0,12).map(e=>`### ${e.title}\n${e.date} · ${e.publisher}\n\n${e.summary}\n\nAnalyst interpretation: ${e.implication}\n\nNext action: ${e.nextAction}\n\nSource: ${e.sourceUrl}\n`).join('\n')+'\n## Notes\n\n'+Object.entries(notes).map(([k,v])=>`${k}: ${v}`).join('\n'));return}let rows;if(action==='export-events')rows=D.events;if(action==='export-entities')rows=D.entities.map(({id,name,type,category,stakePct,status,sourceUrl})=>({id,name,type,category,stakePct,status,sourceUrl}));if(action==='export-portfolio')rows=D.entities.filter(e=>e.riskMonitor).map(e=>({name:e.name,type:e.type,stake:e.stakePct,visibility:e.riskMonitor.visibility,monitor:e.riskMonitor.trigger,source:e.sourceUrl}));if(action==='export-deals')rows=D.opportunities.map(o=>({name:o.name,theme:o.theme,stage:stages[o.id]||o.stage,thesis:o.fit,availability:o.availability,source:o.sourceUrl,notes:notes['deal-'+o.id]||''}));if(action==='export-reports')rows=D.reports.map(r=>({publisher:r.publisher,date:r.report_date,title:r.title,target:r.target_price_idr,previous:r.previous_target_price_idr,rating:r.rating,source:r.sourceUrl}));if(action==='export-saved'){download('GoTo-saved-intelligence.json',JSON.stringify({saved:D.events.filter(e=>saved.includes(e.id)),notes},null,2),'application/json');return}if(rows)download('GoTo-'+action.replace('export-','')+'.csv',csv(rows),'text/csv')}
async function refreshQuotes(){const button=$('[data-action="refresh-quotes"]');if(button){button.disabled=true;button.textContent='Retrieving…'}try{const response=await fetch(D.markets.runtimeQuoteEndpoint.url,{signal:AbortSignal.timeout(18000)});if(!response.ok)throw new Error('Provider unavailable');const payload=await response.json();let updated=0;(payload.quotes||[]).forEach(q=>{const a=D.markets.assets.find(a=>a.ticker===q.ticker);if(a&&Number.isFinite(q.price)){a.price=q.price;a.changePct=q.change_percent;a.provider='TradingView via Cockpit';a.snapshotRetrievedAt=typeof payload.asof==='number'?new Date(payload.asof*1000).toISOString():payload.asof;a.quote.mode='Gateway retrieval snapshot';updated++}});D.markets.runtimeQuoteEndpoint.lastRefreshed=new Date().toISOString();render(true);toast(`${updated} IDX quotes refreshed · snapshot retrieval time`)}catch{toast('Quote provider unavailable. Existing dated snapshots are retained.');if(button){button.disabled=false;button.innerHTML=icon('refresh')+'Refresh IDX quotes'}}}
function model(){let v=id=>Number($('#'+id).value),eb=v('modelEbitda'),mult=v('modelMultiple'),syn=v('modelSynergy'),cost=v('modelCost'),debt=v('modelDebt'),ev=eb*mult;[['modelEbitda',eb,' bn'],['modelMultiple',mult,'×'],['modelSynergy',syn,' bn'],['modelCost',cost,' bn'],['modelDebt',debt,' bn']].forEach(([id,value,unit])=>$('#'+id+'Value').textContent=fmt(value,Number.isInteger(value)?0:1)+unit);$('#modelEV').textContent='Rp'+fmt(ev)+'bn';$('#modelNetDebt').textContent='Rp'+fmt(debt)+'bn';$('#modelEquity').textContent='Rp'+fmt(ev-debt)+'bn';$('#modelIntegration').textContent='Rp'+fmt(cost)+'bn';$('#modelFunding').textContent='Rp'+fmt(ev-debt+cost)+'bn';$('#modelEffective').textContent=fmt((ev+cost)/(eb+syn),2)+'×';$('#modelPayback').textContent=syn>0?fmt(cost/syn,2)+' years':'No positive synergy'}
function bindCommon(root=document){root.querySelectorAll('[data-nav]').forEach(el=>el.onclick=()=>{location.hash=el.dataset.nav;closeDrawer()});root.querySelectorAll('[data-market]').forEach(el=>el.onclick=()=>{S.market=el.dataset.market;S.chartMode='provider';if(view==='markets')render(true);else location.hash='markets';closeDrawer()});root.querySelectorAll('[data-entity]').forEach(el=>{el.onclick=()=>openEntity(el.dataset.entity);if(el.tagName.toLowerCase()==='g')el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();openEntity(el.dataset.entity)}}});root.querySelectorAll('[data-event]').forEach(el=>{el.onclick=()=>openEvent(el.dataset.event);el.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();openEvent(el.dataset.event)}}});root.querySelectorAll('[data-save]').forEach(el=>el.onclick=e=>{e.stopPropagation();save(el.dataset.save)});root.querySelectorAll('[data-deal]').forEach(el=>el.onclick=()=>openDeal(el.dataset.deal));root.querySelectorAll('[data-research]').forEach(el=>el.onclick=()=>openResearch(el.dataset.research));root.querySelectorAll('[data-researchtab]').forEach(el=>el.onclick=()=>{S.researchTab=el.dataset.researchtab;render()});root.querySelectorAll('[data-report]').forEach(el=>el.onclick=()=>openReport(el.dataset.report));root.querySelectorAll('[data-action]').forEach(el=>el.onclick=()=>{let a=el.dataset.action;if(a==='refresh-quotes')refreshQuotes();else if(a==='open-ownership')openOwnership();else if(a==='corporate-timeline')timeline();else exportAction(a)});root.querySelectorAll('[data-filter-news]').forEach(el=>el.onclick=()=>{S.newsFilter=el.dataset.filterNews;location.hash='intelligence'})}
function bindLogoFallbacks(){document.querySelectorAll('.company-logo img').forEach(img=>{img.onerror=()=>{img.hidden=true;const fallback=img.nextElementSibling;if(fallback)fallback.hidden=false};if(img.complete&&img.naturalWidth===0)img.dispatchEvent(new Event('error'))})}
function bindDrawer(){bindCommon($('#drawerBody'));bindLogoFallbacks();$$('[data-note-save]').forEach(el=>el.onclick=()=>{notes[el.dataset.noteSave]=$('#diligenceNote').value;persist();toast('Diligence notes saved in this browser')})}
function inputFilter(selector,stateKey){const el=$(selector);if(!el)return;el.addEventListener('input',()=>{const cursor=el.selectionStart;S[stateKey]=el.value;render(true);const next=$(selector);next.focus();if(next.setSelectionRange)next.setSelectionRange(cursor,cursor)})}
function bindView(){bindCommon($('#main'));bindLogoFallbacks();inputFilter('#newsSearch','newsQuery');inputFilter('#mapSearch','mapQuery');inputFilter('#docSearch','docQuery');inputFilter('#researchSearch','researchQuery');inputFilter('#dealSearch','dealQuery');[['#newsCategory','newsFilter'],['#mapCategory','mapType'],['#docCategory','docFilter'],['#dealTheme','dealFilter'],['#researchCategory','researchCategory']].forEach(([id,key])=>{if($(id))$(id).onchange=e=>{S[key]=e.target.value;render(true)}});[['data-timeframe','timeframe'],['data-chartmode','chartMode'],['data-mapview','mapView'],['data-dealview','dealView'],['data-chart-asset','market']].forEach(([attr,key])=>$$('['+attr+']').forEach(el=>el.onclick=()=>{S[key]=el.getAttribute(attr);if(key==='market'&&S.chartMode!=='compare')S.chartMode='provider';render(true)}));$$('[data-stage]').forEach(el=>el.onchange=()=>{stages[el.dataset.stage]=el.value;persist();render(true);toast('Pipeline stage saved in this browser')});$$('[data-model]').forEach(el=>el.oninput=model);$$('[data-country]').forEach(el=>el.onclick=()=>{S.mapCountry=el.dataset.country;render(true)});$$('[data-georegion]').forEach(el=>el.onclick=()=>{S.mapRegion=el.dataset.georegion;render(true)});if($('#economicPillar'))$('#economicPillar').onchange=e=>{S.economicPillar=e.target.value;render(true)};if($('#geoCountry'))$('#geoCountry').onchange=e=>{S.mapCountry=e.target.value;render(true)};bindWorkbook();if($('#modelEbitda'))model()}
function searchResults(){const term=$('#globalSearchInput').value.trim().toLowerCase();let results=[...D.entities.map(e=>({id:e.id,label:e.name,sub:e.type+' · '+e.sector,type:'Company',kind:'entity'})),...D.events.map(e=>({id:e.id,label:e.title,sub:e.company+' · '+date(e.date),type:'Update',kind:'event'})),...D.documents.map(d=>({id:d.id,label:d.title,sub:d.company+' · '+d.category,type:'Document',kind:'document',url:d.url})),...D.researchLibrary.map(r=>({id:r.id,label:r.title,sub:r.publisher+' · '+r.category,type:'Research',kind:'research'}))].filter(r=>!term||`${r.label} ${r.sub}`.toLowerCase().includes(term)).slice(0,25);$('#searchResults').innerHTML=results.map(r=>`<button class="search-result" data-search-kind="${r.kind}" data-search-id="${r.id}">${icon(r.kind==='entity'?'ecosystem':r.kind==='document'?'research':'intelligence')}<span><b>${esc(r.label)}</b><small>${esc(r.sub)}</small></span>${tag(r.type,'outline')}</button>`).join('')||'<div class="empty">No results found.</div>';$$('[data-search-kind]').forEach(el=>el.onclick=()=>{const r=results.find(r=>r.id===el.dataset.searchId);$('#searchDialog').close();if(r.kind==='entity')openEntity(r.id);else if(r.kind==='event')openEvent(r.id);else if(r.kind==='research')openResearch(r.id);else window.open(r.url,'_blank','noopener')})}
function searchOpen(){if(!D)return;$('#searchDialog').showModal();$('#globalSearchInput').value='';searchResults();$('#globalSearchInput').focus()}
$('#searchOpen').onclick=searchOpen;$('#searchClose').onclick=()=>$('#searchDialog').close();$('#globalSearchInput').oninput=searchResults;$('#drawerClose').onclick=closeDrawer;$('#drawerBackdrop').onclick=closeDrawer;$('#menuToggle').onclick=()=>$('#sidebar').classList.toggle('mobile-open');$('#methodology').onclick=methodology;$('#sourcesOpen').onclick=openSources;$('#watchlistOpen').onclick=openSaved;document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key==='k'){e.preventDefault();searchOpen()}if(e.key==='Escape')closeDrawer()});window.addEventListener('hashchange',()=>render());
Promise.all(['data/dashboard.json','data/valuation-workbook.json'].map(url=>fetch(url,{cache:'no-cache'}).then(r=>{if(!r.ok)throw new Error('Data unavailable');return r.json()}))).then(([data,workbook])=>{D=data;W=workbook;render()}).catch(()=>{$('#main').innerHTML='<div class="empty"><h2>The research dataset could not load.</h2><p>Please refresh or open the dashboard through its hosted URL.</p></div>'});

if(new URLSearchParams(location.search).get('embed')==='1')document.body.classList.add('embedded-explorer');
